  var p = cam.scale, v = p.valueAtTime(t, false)[0];
  keys(p, [t - f2s(3), t + f2s(14)], [[v, v], [v * (amt || 1.08), v * (amt || 1.08)]], [[60, 10], [90, 60]]);
