    var bp = findP(pt, ["Back Page"]); if (bp) { try { bp.setValue(l.index); } catch (x) {} }
    var x1 = (q1[0] - e.o[0]) * e.r, y1 = (q1[1] - e.o[1]) * e.r, x0 = (q0[0] - e.o[0]) * e.r, y0 = (q0[1] - e.o[1]) * e.r;
