  var tn = addFx(l, "ADBE Tint", "Papier alt"); if (tn) { setP(tn, ["Map Black To"], rgb("#1E1A16")); setP(tn, ["Map White To"], rgb("#EFE5D0")); setP(tn, ["Amount to Tint"], 100); }
